/**
 * Bundled city -> coordinate dataset (ticket e5e1aa1), replacing
 * `METRO_AREA_GROUPS`' two hand-curated metro tables with a nationwide
 * lookup that `metroAreas.ts` uses to compute real distance instead of set
 * membership.
 *
 * ---------------------------------------------------------------------------
 * PROVENANCE
 * ---------------------------------------------------------------------------
 *
 * Source: the U.S. Census Bureau's 2023 Gazetteer Files, national Places
 * file -- https://www2.census.gov/geo/docs/maps-data/data/gazetteer/2023_Gazetteer/2023_Gaz_place_national.zip
 * (downloaded 2026-10-10; last-modified per the server: 2023-09-26). Free,
 * public domain (U.S. government work), and the same authority class the
 * deleted `METRO_AREA_GROUPS` table already held itself to (it cited
 * OMB/Census CBSA numbers) -- this is the Census Bureau's OWN place-level
 * data, one level down from the metro-area (CBSA) product that table used.
 * `INTPTLAT`/`INTPTLONG` -- each place's internal point, not a street
 * address or city-hall pin -- are the lat/lon pulled from it unmodified
 * (rounded to 6 decimal places, sub-meter precision, no information lost
 * that matters here).
 *
 * ---------------------------------------------------------------------------
 * FILTERING APPLIED (2026-10-10, from the raw 32,329-row file)
 * ---------------------------------------------------------------------------
 *
 *  - Census Designated Places (LSAD "57" -- unincorporated, statistical-only
 *    boundaries) EXCLUDED: 12,523 rows. A real job posting's location field
 *    names the place a company's office is legally/colloquially in
 *    ("Bellevue, WA"), not a CDP boundary ("East Renton Highlands CDP") --
 *    keeping them would have more than doubled the within-radius candidate
 *    count for a dense metro (measured: 273 non-filtered WA places within 60
 *    miles of Seattle before this exclusion, 98 after), for essentially zero
 *    real-posting benefit. Costs coverage only in the hypothetical case of a
 *    posting that names an unincorporated community by name, which is
 *    unobserved in this app's real data.
 *  - Rows outside the 50 states + DC EXCLUDED: 292 (Puerto Rico, Guam,
 *    American Samoa, the Northern Mariana Islands, the U.S. Virgin Islands).
 *    None of these is a region this app's `REGION_CODE_BY_NAME` table
 *    already recognizes, so a coordinate for one would be unreachable by the
 *    region guard regardless.
 *  - Each name had its LSAD suffix word stripped ("Bellevue city" ->
 *    "bellevue"), any parenthetical alternate-name annotation removed
 *    ("Fredonia (Biscoe) town" -> "fredonia"), and periods removed ("St.
 *    Louis" would become "st louis" -- would, not does; see below).
 *  - 8 rows REJECTED outright after that normalization, because the
 *    resulting name still contained a character this file's lookup can't
 *    safely anchor a `\b...\b` word-boundary pattern on (a diacritic,
 *    a slash, or a comma): Utqiagvik AK, La Canada Flintridge CA, Canon City
 *    CO, Islamorada FL, the Louisville/Jefferson County and
 *    Hartsville/Trousdale County consolidated city-counties (KY, TN),
 *    Espanola NM, and the Lynchburg/Moore County consolidated government
 *    (TN). Each is a real, known coverage gap -- "include nearby cities"
 *    cannot resolve a phrase naming one of these eight -- recorded here
 *    rather than silently dropped. "St. Louis", "Winston-Salem" and similar
 *    hyphenated/abbreviated names ARE kept (hyphens and apostrophes are not
 *    regex metacharacters and need no escaping), but a posting or phrase
 *    spelled "St. Louis" with the period intact will not match "st louis"
 *    the way "St Louis" would -- `cityPattern`'s `\s+`-for-space relaxation
 *    has no equivalent period tolerance. Unmeasured against this app's real
 *    corpus; accepted the same way every other normalization gap in this
 *    module is: it costs coverage for a specific spelling, never a false
 *    positive.
 *  - Of the 18 cases where normalization produced the exact same (state,
 *    name) pair twice (e.g. two historically-distinct "Oakwood"s in OH),
 *    BOTH rows are kept, not deduped -- `nearbyCitiesWithinRadius` unions
 *    every coordinate for a name, so a phrase near either one is found.
 *
 * Result: 19,506 rows, sorted by (state, name, lat, lon) for a reviewable
 * diff. NOT reformatted by Prettier (see .prettierignore) for the same
 * reason the Lever/Greenhouse fixture captures aren't: this is a verbatim
 * derived-from-source data table, and "verbatim" is the property worth
 * keeping.
 *
 * ---------------------------------------------------------------------------
 * FORMAT
 * ---------------------------------------------------------------------------
 *
 * One row per line, `|`-delimited (not a JS array literal -- 19,506 tuple
 * literals would be slow for Prettier and tsc to no benefit): USPS state
 * code, lowercase place name, latitude, longitude. Parsed once at module
 * load into `CITY_COORDINATES` below.
 */

interface RawCityCoordinate {
  readonly state: string;
  readonly name: string;
  readonly lat: number;
  readonly lon: number;
}

